import { test, expect } from '@playwright/test';

test.describe('Async Operation Cancellation with Abort Button', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/async-operation');
  });

  test('should cancel an ongoing async operation when Abort button is clicked', async ({ page }) => {
    // Start the async operation
    const startButton = page.getByRole('button', { name: /start/i });
    await startButton.click();

    // Verify operation is running
    const statusText = page.getByText(/running/i);
    await expect(statusText).toBeVisible();

    // Wait briefly to ensure operation has started
    await page.waitForTimeout(500);

    // Click the Abort button
    const abortButton = page.getByRole('button', { name: /abort/i });
    await abortButton.click();

    // Verify operation is cancelled
    await expect(statusText).not.toBeVisible();
    const cancelledMessage = page.getByText(/operation cancelled/i);
    await expect(cancelledMessage).toBeVisible();

    // Verify error state is displayed
    const errorDisplay = page.getByText(/operation cancelled/i);
    await expect(errorDisplay).toBeVisible();
  });

  test('should handle successful completion when Abort button is not clicked', async ({ page }) => {
    // Start the async operation
    const startButton = page.getByRole('button', { name: /start/i });
    await startButton.click();

    // Wait for operation to complete
    const statusText = page.getByText(/completed successfully/i);
    await expect(statusText).toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText(/operation completed successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify status is no longer running
    const runningStatus = page.getByText(/running/i);
    await expect(runningStatus).not.toBeVisible();

    // Verify result data is displayed
    const resultData = page.getByText(/result data/i);
    await expect(resultData).toBeVisible();
  });
});
